class MinStack {
  private items: number[] = [];
  private mins: number[] = [];

  push(val: number): void {
    this.items.push(val);
    // <= keeps a copy for every duplicate of the minimum
    if (this.mins.length === 0 || val <= this.mins[this.mins.length - 1]) this.mins.push(val);
  }

  pop(): void {
    const v = this.items.pop();
    if (v === this.mins[this.mins.length - 1]) this.mins.pop();
  }

  top(): number {
    return this.items[this.items.length - 1];
  }

  getMin(): number {
    return this.mins[this.mins.length - 1];
  }
}

